// Public endpoint: never trust the body. Clamp everything, drop anything weird.
const b = $json.body || {};
const s = (v, n) => String(v == null ? '' : v).replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, n);
const name = s(b.name, 60) || 'there';
const out = {
  name: name.split(/\s+/)[0],
  phone: s(b.phone, 30),
  city: s(b.city, 60) || 'your area',
  issue: s(b.issue, 400) || 'no cooling',
};
if (!out.issue) throw new Error('issue required');
return [{ json: out }];

