const b = $json.body || {};
const token = String(b.token || '').replace(/[^a-f0-9]/gi, '').slice(0, 64);
const text = String(b.text || '').replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, 400);
if (!token || !text) throw new Error('token and text required');
return [{ json: { token, text } }];

