// The model is told to answer with bare JSON. If it ever wraps it in prose or a
// fence, salvage the object instead of failing the demo in front of a prospect.
const raw = String($json.content?.[0]?.text || '').trim();
let d = null;
try { d = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { d = JSON.parse(m[0]); } catch (e2) { d = null; } }
}
if (!d || !d.message) d = { message: raw.slice(0, 320) || "Got it - a technician will call you shortly to confirm a time.", book: false };
// The window is decided HERE and shipped as a finished label. Letting the browser
// re-derive it from a UTC timestamp made the card say 12-4pm while the text said
// 8-12 - a prospect reads that as the system contradicting itself.
const hint = String(d.slot_hint || 'tomorrow_am');
const WINDOWS = {
  today_pm:    { addDays: 0, hour: 13, label: '12:00pm - 4:00pm' },
  tomorrow_am: { addDays: 1, hour: 9,  label: '8:00am - 12:00pm' },
  tomorrow_pm: { addDays: 1, hour: 13, label: '12:00pm - 4:00pm' },
  this_week:   { addDays: 2, hour: 9,  label: '8:00am - 12:00pm' },
};
const w = WINDOWS[hint] || WINDOWS.tomorrow_am;
const slot = new Date();
slot.setDate(slot.getDate() + w.addDays);
slot.setHours(w.hour, 0, 0, 0);
const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const dayWord = w.addDays === 0 ? 'Today' : (w.addDays === 1 ? 'Tomorrow' : DAYS[slot.getDay()]);
const slot_label = dayWord + ', ' + MONTHS[slot.getMonth()] + ' ' + slot.getDate() + ' - ' + w.label;
return [{ json: {
  session_id: $('Log Lead Text').item.json.session_id,
  message: String(d.message).slice(0, 320),
  book: !!d.book,
  job_type: String(d.job_type || 'HVAC service call').slice(0, 60),
  slot_at: slot.toISOString(),
  slot_label,
} }];
